}
.clone-demo-k712 .main-menu-wrapper ul.main-menu-list .yiji > li .li_item a {
  white-space: nowrap;
  overflow: visible;
  text-overflow: clip;
  text-align: left;
}
.clone-demo-k712 .main-menu-wrapper ul.main-menu-list > li ul.yiji li ul.erji {
  width: max-content;
  min-width: 100%;
}
.clone-demo-k712 .main-menu-wrapper ul.main-menu-list > li ul.yiji li:hover ul.erji li {
  width: 100%;
  white-space: nowrap;
  padding: 0 20px;
  box-sizing: border-box;
  text-align: left;
}

